package dev.industrialtechnology.test;
import java.util.*;import java.io.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;
import cpw.mods.fml.common.FMLCommonHandler;import cpw.mods.fml.common.eventhandler.SubscribeEvent;import cpw.mods.fml.common.gameevent.TickEvent;
import dev.industrialtechnology.core.*;
import li.cil.oc.api.machine.Machine;import li.cil.oc.api.machine.MachineHost;import li.cil.oc.api.network.Connector;import li.cil.oc.api.internal.TextBuffer;
import net.minecraft.client.Minecraft;import net.minecraft.client.gui.GuiMainMenu;import net.minecraft.world.*;import net.minecraft.server.MinecraftServer;import net.minecraft.entity.player.EntityPlayerMP;import net.minecraft.tileentity.TileEntity;import net.minecraft.item.*;import net.minecraft.inventory.IInventory;import net.minecraft.init.Blocks;import net.minecraft.util.ScreenShotHelper;import org.lwjgl.opengl.GL11;
/** Original OC OpenOS, case/screen GUIs and network input in a disposable integrated world. */
public final class OpenComputersClientChecks {
 private final List<String> results=Collections.synchronizedList(new ArrayList<String>());private int phase,wait=30,tries;private boolean done;private volatile Throwable failure;private Machine machine;private TileEntity screen;private TextBuffer buffer;
 public void init(){FMLCommonHandler.instance().bus().register(this);}
 static void check(boolean ok,String why){if(!ok)throw new AssertionError(why);}
 void pass(String text){results.add("PASS: "+text);IndustrialTechnology.log.info("OC CLIENT PASS: "+text);}
 static WorldServer world(){return MinecraftServer.getServer().worldServerForDimension(0);}static EntityPlayerMP player(){return(EntityPlayerMP)MinecraftServer.getServer().getConfigurationManager().playerEntityList.get(0);}
 static ItemStack stack(String name){check(li.cil.oc.api.Items.get(name)!=null,"Missing "+name);return li.cil.oc.api.Items.get(name).createItemStack(1);}
 static TileEntity place(String name,int x){WorldServer w=world();w.setBlock(x,69,24,Blocks.stone,0,3);EntityPlayerMP p=player();ItemStack item=stack(name);p.inventory.mainInventory[0]=item;check(item.tryPlaceItemIntoWorld(p,w,x,69,24,1,.5f,1,.5f),"Cannot place "+name);return w.getTileEntity(x,70,24);}
 static void insert(IInventory inv,String name){ItemStack item=stack(name);for(int i=0;i<inv.getSizeInventory();i++)if(inv.getStackInSlot(i)==null&&inv.isItemValidForSlot(i,item)){inv.setInventorySlotContents(i,item);return;}throw new AssertionError("No slot for "+name);}
 void server(Runnable action){ServerWork.enqueue(()->{try{action.run();}catch(Throwable e){failure=e;IndustrialTechnology.log.error("OC client server check",e);}});}
 String text(){StringBuilder s=new StringBuilder();if(buffer!=null)for(int y=0;y<buffer.getHeight();y++){for(int x=0;x<buffer.getWidth();x++)s.append(buffer.get(x,y));s.append('\n');}return s.toString();}
 void shot(Minecraft mc,String name){check(GL11.glGetError()==0,"OpenGL error");ScreenShotHelper.saveScreenshot(mc.mcDataDir,name,mc.displayWidth,mc.displayHeight,mc.getFramebuffer());}
 @SubscribeEvent public void tick(TickEvent.ClientTickEvent e){if(done||e.phase!=TickEvent.Phase.END||--wait>0)return;Minecraft mc=Minecraft.getMinecraft();try{
  if(failure!=null)throw new AssertionError("Server check",failure);
  if(phase==0){if(!(mc.currentScreen instanceof GuiMainMenu)){wait=20;return;}mc.gameSettings.guiScale=2;mc.gameSettings.renderDistanceChunks=3;mc.gameSettings.pauseOnLostFocus=false;mc.gameSettings.showInventoryAchievementHint=false;WorldSettings settings=new WorldSettings(290,WorldSettings.GameType.CREATIVE,false,false,WorldType.FLAT);settings.func_82750_a("2;7;1;");mc.launchIntegratedServer("oc-visual-test","Disposable OpenComputers QA",settings);phase=1;wait=70;return;}
  if(mc.thePlayer==null||mc.theWorld==null){check(++tries<100,"World join timeout");wait=10;return;}
  if(phase==1){mc.displayGuiScreen(null);server(()->{EntityPlayerMP p=player();p.capabilities.isFlying=true;p.sendPlayerAbilities();p.setPositionAndUpdate(21.5,70,21.5);IInventory computer=(IInventory)place("caseCreative",20);for(String n:new String[]{"cpu3","ram6","ram6","graphicsCard3","hdd3","luaBios","openos"})insert(computer,n);screen=place("screen3",21);place("keyboard",22);machine=((MachineHost)computer).machine();try{buffer=(TextBuffer)OpenComputersServerChecks.invoke(screen,"buffer");}catch(Exception ex){throw new RuntimeException(ex);}});phase=6;tries=0;wait=30;return;}
  if(phase==6){server(()->{((Connector)machine.node()).changeBuffer(1000000);check(machine.start()||machine.isRunning(),"Cannot boot OpenOS: "+machine.lastError());});phase=2;wait=100;return;}
  if(phase==2){String text=text();if(!text.contains("/ #")&&!text.contains("OpenOS")&&!text.contains("/home")){check(++tries<30,"OpenOS boot timeout: "+text+" error="+(machine==null?"no machine":machine.lastError()));wait=20;return;}check(machine.isRunning(),"OpenOS stopped");pass("Original OpenOS boots from its supplied floppy with original Lua BIOS and GPU/screen");Files.write(new File(mc.mcDataDir,"openos-boot.txt").toPath(),Arrays.asList(text),StandardCharsets.UTF_8);server(()->world().getBlock(20,70,24).onBlockActivated(world(),20,70,24,player(),2,.5f,.5f,.5f));phase=3;wait=30;return;}
  if(phase==3){check(mc.currentScreen!=null&&mc.currentScreen.getClass().getName().equals("li.cil.oc.client.gui.Case"),"Original case GUI missing: "+mc.currentScreen);shot(mc,"oc-original-case.png");pass("Original case hardware GUI and textures render without OpenGL errors");mc.thePlayer.closeScreen();mc.theWorld.getBlock(21,70,24).onBlockActivated(mc.theWorld,21,70,24,mc.thePlayer,2,.5f,.5f,.5f);phase=4;wait=30;return;}
  if(phase==4){check(mc.currentScreen!=null&&mc.currentScreen.getClass().getName().equals("li.cil.oc.client.gui.Screen"),"Original screen GUI missing: "+mc.currentScreen);shot(mc,"oc-original-openos.png");pass("Original full-screen terminal renders the live OpenOS framebuffer");TextBuffer clientBuffer;try{clientBuffer=(TextBuffer)OpenComputersServerChecks.invoke(mc.theWorld.getTileEntity(21,70,24),"buffer");}catch(Exception ex){throw new RuntimeException(ex);}clientBuffer.clipboard("echo OC-INPUT-OK",mc.thePlayer);clientBuffer.keyDown('\r',28,mc.thePlayer);clientBuffer.keyUp('\r',28,mc.thePlayer);phase=5;wait=70;return;}
  if(phase==5){check(text().contains("OC-INPUT-OK"),"Keyboard command not received: "+text());shot(mc,"oc-original-shell-command.png");pass("Original screen input packets reach OpenOS and execute a shell command");finish(mc,false);}
 }catch(Throwable t){results.add("FAIL: phase "+phase+" :: "+t);IndustrialTechnology.log.error("OpenComputers client QA",t);ScreenShotHelper.saveScreenshot(mc.mcDataDir,"oc-failure.png",mc.displayWidth,mc.displayHeight,mc.getFramebuffer());finish(mc,true);}}
 void finish(Minecraft mc,boolean failed){done=true;try{results.add("Failed: "+(failed?1:0));Files.write(new File(mc.mcDataDir,"oc-client.txt").toPath(),results,StandardCharsets.UTF_8);}catch(Exception ex){IndustrialTechnology.log.error("OC report",ex);}mc.shutdown();}
}
